// Compute set differences:
// A = Zapier-fired entries (set of source-form + entry_id)
// B = n8n-received entries (set of External_Submission_Id__c)
// C = entries with Status__c='written'
// Diff: A - B  (Zapier received, n8n missed — ALERT-WORTHY)
//       B - A  (n8n received, Zapier didn't — should be 0 in parallel mode)
//       A ∩ B - C  (both received, neither wrote — investigate)

const zapierTasks = $input.first().json.zapierTasks || [];
const n8nLogs = $input.first().json.n8nLogs || [];
const n8nExecutions = $input.first().json.n8nExecutions || [];

const zapierKeys = new Set(zapierTasks.map(t => `${t.source_form}:${t.entry_id}`));
const n8nKeys = new Set(n8nLogs.map(l => `${l.Source__c}:${l.External_Submission_Id__c}`));
const writtenKeys = new Set(n8nLogs.filter(l => l.Status__c === 'written').map(l => `${l.Source__c}:${l.External_Submission_Id__c}`));

const diffAB = [...zapierKeys].filter(k => !n8nKeys.has(k));   // Zapier fired but n8n didn't receive
const diffBA = [...n8nKeys].filter(k => !zapierKeys.has(k));   // n8n received but Zapier didn't (rare)
const diffNeitherWrote = [...zapierKeys].filter(k => n8nKeys.has(k) && !writtenKeys.has(k));

const summary = {
  hour: new Date().toISOString(),
  total_zapier: zapierKeys.size,
  total_n8n: n8nKeys.size,
  total_written: writtenKeys.size,
  diff_A_minus_B: diffAB.length,
  diff_B_minus_A: diffBA.length,
  diff_neither_wrote: diffNeitherWrote.length,
  top_5_A_minus_B: diffAB.slice(0, 5),
  top_5_B_minus_A: diffBA.slice(0, 5),
  top_5_neither: diffNeitherWrote.slice(0, 5),
  page_oncall: diffAB.length > 0
};
return [{ json: summary }];

